tests:
assert histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
assert histogram('a b b a') == {'a': 2, 'b': 2}
assert histogram('a b c a b') == {'a': 2, 'b': 2}
assert histogram('b b b b a') == {'b': 4}
assert histogram('') == {}

# Single token
assert histogram('a') == {'a': 1}

# Repeated single letter
assert histogram('a a a') == {'a': 3}

# Large scale tie between two letters
s = ' '.join(['a'] * 500 + ['b'] * 400 + ['c'] * 500)
assert histogram(s) == {'a': 500, 'c': 500}

# Large scale single maximum
s2 = ' '.join(['z'] * 1000 + ['y'] * 999)
assert histogram(s2) == {'z': 1000}
